// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2009, "2-3", [{"author":"Е. Добрушина","question":"Если папа — <em>гусь</em>, то сын — <em>гусёнок</em>. А мама?","choices":["<em>гусиха</em>","<em>гусица</em>","<em>гусятина</em>","<em>гусыня</em>","среди ответов (А)–(Г) нет правильного."],"key":"Г","review":["Гусиная семья","«Гусь» называет папу, «гусёнок» — его детёныша. Для мамы ищи отдельное название взрослой птицы.","В русском языке её называют «гусыня». А слово «гусятина» обозначает гусиное мясо."]},{"author":"П. Аркадьев","question":"Кто из них <strong>не</strong> музыкант?","choices":["пианист","гармонист","баянист","флейтист","трубочист."],"key":"Д","review":["Кто играет музыку?","Пианист играет на пианино, гармонист на гармони, баянист на баяне, флейтист на флейте.","Трубочист чистит печные трубы. В его названии тоже есть «труба», но здесь речь о дымоходе, а не о музыкальном инструменте."]},{"author":"И. Рубанов","question":"Косте подарили щенка. Как Костя увидел его, так сразу и назвал Бубликом. Какой у Бублика хвост?","choices":["колечком","трубой","прутом","свисающий","обрубленный."],"key":"А","review":["Хвост щенка","Вспомни, как выглядит бублик. Он круглый, и в середине у него отверстие.","Похожую форму имеет хвост, свёрнутый в колечко. Так можно объяснить, почему щёнок получил кличку Бублик."]},{"author":"Б. Иомдин","question":"В каком выражении слово <em>да</em> значит не то, что в остальных?","choices":["<em>рожки да ножки</em>","<em>Иван да Марья</em>","<em>ай да умница</em>","<em>вокруг да около</em>","<em>тишь да гладь</em>."],"key":"В","review":["Значения слова «да»","Попробуй заменить «да» на «и». Получается «рожки и ножки», «Иван и Марья», «вокруг и около», «тишь и гладь».","«Ай да умница!» — восклицание, которым хвалят. В нём «ай да» звучит вместе, а замена на «и» разрушает выражение."]},{"author":"Н. Валеева","question":"В русском языке есть слова, обозначающие «голоса» разных животных и птиц: ку-ку, иа, кудах-тах-тах и т. п. Из пяти данных в ответах слов четыре обозначают «голоса» животных и птиц, а одно — нет. Какое?","choices":["<em>гав-гав</em>","<em>и-го-го</em>","<em>кис-кис</em>","<em>кря-кря</em>","<em>кукареку</em>."],"key":"В","review":["Кто как подаёт голос","Соотнеси звуки и животных: «гав-гав» говорит собака, «и-го-го» — лошадь, «кря-кря» — утка, «кукареку» — петух.","«Кис-кис» произносит человек, когда подзывает кошку. Сама кошка мяукает."]},{"author":"Е. Добрушина","question":"<em>Хотя шкаф был высоким, котёнок умудрился __прыгнуть на него прямо с пола</em>. Какая приставка здесь пропущена?","choices":["<em>от</em>","<em>вы</em>","<em>пере</em>","<em>с</em>","<em>за</em>."],"key":"Д","review":["Котёнок и высокий шкаф","Следи за направлением: котёнок был на полу, а оказался наверху. «Спрыгнуть» означало бы двигаться сверху вниз.","Подходит «запрыгнуть на шкаф»: приставка «за-» здесь передаёт прыжок на предмет. Проверь, что и начало, и конец движения совпадают с условием."]},{"author":"Г. Крейдлин","question":"Какое из этих слов по смыслу сильно отличается от остальных?","choices":["<em>очки</em>","<em>бинокль</em>","<em>микроскоп</em>","<em>наушники</em>","<em>лупа</em>."],"key":"Г","review":["Приборы и органы чувств","Очки, бинокль, микроскоп и лупа помогают лучше рассмотреть то, что плохо видно без них.","Наушники нужны для слуха: через них слушают звуки. От приборов для зрения они отличаются назначением."]},{"author":"Л. Добрушин и Е. Добрушина","question":"У Лёвы в коллекции игрушечных животных есть корова, коза, крокодил, лягушка, кит, кошка, ворона и курица. Игрушки стоят на полке так, что их названия идут в алфавитном порядке. Между какими игрушками стоит на полке кошка?","choices":["между коровой и крокодилом","между крокодилом и курицей","между вороной и китом","между курицей и лягушкой","между козой и коровой."],"key":"А","review":["Кошка на полке","Ищи слова рядом с «кошка» среди начинающихся на «к». Раньше «ко-» идёт «ки-», позже идут «кр-» и «ку-».","Среди слов на «ко-» буквы «з», «р», «ш» идут по порядку: коза, корова, кошка. Сразу за ними начинается «кр-», поэтому соседи кошки — корова и крокодил."]},{"author":"С. Бурлак","question":"Какое слово <strong>не</strong> родственно остальным?","choices":["<em>смешить</em>","<em>смешать</em>","<em>смешной</em>","<em>насмешливый</em>","<em>смех</em>."],"key":"Б","review":["Похожие слова","Слова «смешить», «смешной» и «насмешливый» связаны со смехом. В этих родственных словах «х» в корне чередуется с «ш».","«Смешать» значит соединить, как в «смешать краски». Это слово родственно «мешать», так что похожее звучание здесь обманывает."]},{"author":"Н. Добрушина","question":"Дениске идёт девятый год. Это значит, что ему","choices":["больше девяти, но меньше десяти","больше восьми, но меньше девяти","больше семи, но меньше восьми","больше девяти","меньше восьми."],"key":"Б","review":["Девятый год Дениски","Первый год жизни идёт от рождения до первого дня рождения. Значит, номер текущего года на один больше числа уже прожитых полных лет.","Девятый год начался после восьмого дня рождения и закончится к девятому. Дениске уже больше восьми, но ещё меньше девяти."]},{"author":"И. Рубанов","question":"Маша составляла кроссворд. Ей осталось придумать вопрос для строки из трёх клеточек, где в первой клеточке уже стояла буква <em>м</em>, а в третьей — буква <em>ч</em>. Она попросила друзей помочь. Коля предложил вопрос: «<em>Холодное оружие</em>», Соня: «<em>То,</em> <em>чем играют в футбол</em>», а Катя: «<em>Встреча двух команд</em>». Кто из них дал плохой совет?","choices":["все трое","Коля","Соня","Катя","все советы хорошие."],"key":"Г","review":["Три клетки кроссворда","Из подсказок Коли и Сони получаются «меч» и «мяч». Оба слова занимают три клетки и подходят под рисунок «м_ч».","Встреча команд — «матч». В этом слове четыре буквы, так что оно не влезет. Плохой совет дала Катя."]},{"author":"И. Иткин","question":"В каком предложении слово <em>красит</em> значит <strong>не</strong> то, что в остальных?","choices":["<em>Наша бабушка никогда не красит волосы</em>.","<em>Этот поступок его не красит</em>.","<em>Уже три часа Том Сойер красит забор</em>.","<em>Фёдор Евлампьевич строит отличные летние домики и сам их красит</em>.","во всех этих предложениях слово <em>красит</em> значит одно и то же."],"key":"Б","review":["Значения слова «красит»","Волосы, забор и домики можно покрыть краской. В этих трёх предложениях слово имеет прямое значение.","«Поступок его не красит» значит «поступок не делает ему чести». Здесь речь о том, каким человек выглядит в глазах других."]},{"author":"Е. Муравенко","question":"Расшифруйте ребусы и укажите, что лишнее.","choices":["[ВЕСНА]","[МАРТ]","[ЛЕТО]","[ОСЕНЬ]","[ЗИМА]."],"key":"Б","review":["Пять ребусов","В ребусе Б две запятые перед рамой убирают две первые буквы, и получается «ма». У слова «рот» зачёркнута «о», поэтому остаётся «рт». Вместе выходит «март».","Остальные ребусы дают весну, лето, осень и зиму. Все четыре — времена года, а март является только одним месяцем."],"figure":{"options":[{"src":"assets/medvezhonok/2009/2-3-13-1.webp","width":119,"height":54,"pixelWidth":119,"pixelHeight":54,"description":"Маленькая с внутри е, затем луна с двумя запятыми перед ней"},{"src":"assets/medvezhonok/2009/2-3-13-2.webp","width":134,"height":67,"pixelWidth":134,"pixelHeight":67,"description":"Рама с двумя запятыми перед ней, затем рот с зачёркнутой буквой о"},{"src":"assets/medvezhonok/2009/2-3-13-3.webp","width":140,"height":55,"pixelWidth":140,"pixelHeight":55,"description":"Лес с запятой после него, число 100 с запятой перед ним"},{"src":"assets/medvezhonok/2009/2-3-13-4.webp","width":194,"height":75,"pixelWidth":194,"pixelHeight":75,"description":"Нос и пень, перед каждым рисунком запятая"},{"src":"assets/medvezhonok/2009/2-3-13-5.webp","width":61,"height":71,"pixelWidth":61,"pixelHeight":71,"description":"Открытый замок с двумя запятыми после него, под ним запись 1И32"}],"onlyPictures":true}},{"author":"Л. Фёдорова","question":"Вот четверостишие из известного стихотворения Самуила Маршака:\n«Глубокоуважаемый вагоноуважатый!\nВагоноуважаемый глубокоуважатый!\nВо что бы то ни стало мне надо выходить.\nНельзя ли у трамвала вокзай остановить?»\nСколько несуществующих слов употребил «человек рассеянный с улицы Бассейной»?","choices":["два","три","четыре","пять","шесть."],"key":"Г","review":["Слова рассеянного","В первых двух строках четыре длинных слова. Из них есть в языке только «глубокоуважаемый», поэтому вычеркни его и насчитай три выдуманных.","В последней строке он перепутал «трамвай» и «вокзал», получились «трамвала» и «вокзай». Прибавь эти два к трём и получишь пять."]},{"author":"Н. Валеева","question":"Дом — крыша, слон — хобот, нога — колено, дерево — …?","choices":["лес","берёза","ветка","куст","пень."],"key":"В","review":["Предмет и его часть","Крыша — часть дома, хобот — часть тела слона, колено — часть ноги. Ищи часть дерева.","Ветка растёт на стволе и составляет часть дерева. Берёза — целое дерево, лес состоит из деревьев, а пень остаётся после того, как дерево срубили."]},{"author":"А. Иткин и И. Иткин","question":"Маша протянула младшему брату леденец и сказала: «<em>Л...жи и молчи!</em>» Какими буквами можно заполнить пропуск?","choices":["только <em><strong>е</strong></em>","только <em><strong>и</strong></em>","только <em><strong>о</strong></em>","только <em><strong>е</strong></em> <strong>и</strong> <em><strong>и</strong></em>","<em><strong>е</strong></em>, <em><strong>и</strong></em>, <em><strong>о</strong></em>."],"key":"Г","review":["Леденец и пропущенная буква","С «е» получается «лежи». Так можно попросить брата остаться лежать и вести себя тихо.","С «и» получится «лижи»: Маша как раз протягивает леденец. «Ложи» в литературном русском заменяют на «клади», поэтому подходят только «е» и «и»."]},{"author":"С. Бурлак","question":"Библиотекарь Д. Е. Фолиантов занимался расстановкой книг в шкафу номер 17. Что он делал с книгами?","choices":["расстаивал","расстановливал","расстановлял","расставливал","расставлял."],"key":"Д","review":["Библиотекарь у шкафа","«Расстановка книг» означает, что книги распределяют по местам. Скажи, что уже сделал библиотекарь: «расставил книги».","О процессе говорят «расставлял книги». Корень «-став-» остаётся тем же, что в «поставил» и «расставил»."]},{"author":"И. Иткин","question":"Лёва загадал одну из семи нот и назвал Лёше одну букву, входящую в её название. Лёша сразу смог догадаться, какая нота загадана. Какую букву назвал Лёва?","choices":["<em>л</em>","<em>и</em>","<em>с</em>","<em>о</em>","<em>а</em>."],"key":"Д","review":["Семь нот","Запиши все названия: до, ре, ми, фа, соль, ля, си. «Л», «и», «с» и «о» встречаются как минимум в двух названиях каждое.","«А» есть только в «фа». Эта буква сразу выдаёт загаданную ноту."]},{"author":"И. Рубанов","question":"У Миши светлые волосы, у его папы — чёрные, у брата — рыжие, а дедушка Миши совсем седой. Кто из них брюнет?","choices":["Миша","папа","брат","дедушка","никто."],"key":"Б","review":["Цвет волос","Соотнеси цвета с людьми: Миша светловолосый, его брат рыжий, дедушка седой.","Брюнетом называют темноволосого мужчину или мальчика. В этой семье чёрные волосы у папы."]},{"author":"Е. Добрушина","question":"Говорят <em>два дома</em>, но <em>семь домов</em>. Как видим, слово <em>два</em> требует от слова <em>дом</em> окончания -<em>а</em>, а слово <em>семь</em> — окончания -<em>ов</em>. Какое из названий чисел ведёт себя в таких словосочетаниях точно так же, как <em>два</em>?","choices":["<em>пять</em>","<em>двадцать</em>","<em>двадцать</em> <em>один</em>","<em>двадцать</em> <em>семь</em>","<em>сто</em> <em>четыре</em>."],"key":"Д","review":["Числа рядом с домом","Скажи вслух «пять домов», «двадцать домов», «двадцать один дом» и «двадцать семь домов». У слова «дом» нигде не получилось окончания «-а».","«Четыре дома» и «сто четыре дома» заканчиваются так же, как «два дома». Из данных чисел только «сто четыре» даёт нужную форму."]},{"author":"Б. Иомдин","question":"Закончите стихотворение Германа Лукомникова:\nла.\nНе надо\nзвать врача.\nНачинай\nчитать\n_______-","choices":["<em>молча</em>","<em>уча</em>","<em>снача</em>","<em>круча</em>","<em>сплеча</em>."],"key":"В","review":["Оборванная строка","В конце оставлен знак переноса, поэтому последнюю строку нужно соединить с первой. Первая строка начинается с «ла.»","«Снача-» и «ла» дают «сначала». Фраза «Начинай читать сначала» подсказывает вернуться в начало стихотворения и заодно завершает его."]},{"author":"И. Иткин","question":"В каком слове все звуки разные?","choices":["<em>дрозд</em>","<em>круг</em>","<em>кружка</em>","<em>лыжи</em>","<em>пробка</em>."],"key":"А","review":["Повторяющиеся звуки","Слушай звуки, а не буквы: «круг» произносится с двумя [к], «кружка» тоже, в «лыжи» два [ы], в «пробка» два [п].","В «дрозд» последние буквы «зд» оглушаются до [ст]. Получаются [д], [р], [о], [с], [т], все разные."]},{"author":"Е. Муравенко","question":"Из слова <em>солистка</em>, убрав несколько букв и не меняя порядка оставшихся, можно получить слово <em>лиса</em>. Из всех данных слов, кроме одного, таким образом тоже можно получить названия животных. Из какого слова название животного так не получится?","choices":["<em>комбайн</em>","<em>полдень</em>","<em>полость</em>","<em>наволочка</em>","<em>курорт</em>."],"key":"А","review":["Животные внутри слов","Сохраняя порядок букв, оставь «олень» из «полдень», «лось» из «полость», «волк» из «наволочка», «крот» из «курорт».","Остаётся «комбайн». Например, для «кабана» здесь буквы «а» и «б» стоят не в том порядке, да и второй «а» нет. Из набора «к, о, м, б, а, й, н» название животного не складывается."]},{"author":"Б. Иомдин и Ю. Халеева","question":"Закончите стихотворение Ренаты Мухи:\nДождик тянется за Тучкой,\nШепчет Тучке на ходу:\n«Мама, скучно,\nмама, скучно!\nМама!\nМожно я … ?»","choices":["<em>уйду</em>","<em>приду</em>","<em>пойду</em>","<em>сойду</em>","<em>зайду</em>."],"key":"В","review":["Дождик и Тучка","Все варианты рифмуются со словом «ходу», поэтому ищи подсказку в сюжете. Дождик ребёнком просит у Тучки разрешения, а действие связано с дождём.","«Дождь пойдёт» — так говорят о начале дождя. В строке «Можно я пойду?» слышится и этот смысл, и обычная детская просьба уйти."]},{"author":"Б. Иомдин","question":"Когда Саше Яновской, героине повести Александры Бруштейн «Дорога уходит в даль», было четыре года, её впервые взяли в театр. Вернувшись, Саша сказала с огорчением: «<em>А бедного Снепорока не показали почему-то...</em>». А какую пьесу смотрела Саша?","choices":["«Пирог»","«Пророк»","«Бедность не порок»","«Бедные люди»","«Белый снег»."],"key":"В","review":["Саша в театре","В слове «Снепорок» слышно «не порок». Саша соединила эти слова, как будто услышала имя человека.","В названии «Бедность не порок» она приняла «бедность» за указание, что герой бедный. Вот почему ожидала увидеть «бедного Снепорока»."]},{"author":"И. Иткин","question":"Илья и Света придумали игру в города по особым правилам. Оказалось, что игра очень трудная и не на все буквы можно подобрать подходящие названия. Всё-таки на букву <strong><em>Б</em></strong> они смогли придумать город <em>Бердичев</em>, на <strong><em>Д</em></strong> — <em>Душанбе</em>, на <strong><em>М</em></strong> — <em>Милан</em>, на <strong><em>П</em></strong> — <em>Павлодар</em>. Какой город подходит на букву <strong><em>Т</em></strong>?","choices":["<em>Тарту</em>","<em>Торопец</em>","<em>Ташкент</em>","<em>Тбилиси</em>","ни один из вариантов (А)–(Г) не подходит."],"key":"А","review":["Игра в города","Сравни первые и последние буквы: Бердичев — Б и В, Душанбе — Д и Е, Милан — М и Н, Павлодар — П и Р. Вторые буквы каждой пары идут в алфавите сразу после первых.","Сразу после «Т» стоит «У». Из предложенных городов только «Тарту» начинается на «Т» и оканчивается на «У»."]},{"author":"С. Бурлак","question":"В предложении <em>Рубит ёлку лесоруб</em> понятно, что подлежащее — <em>лесоруб</em>. А в каком предложении нельзя однозначно определить, где подлежащее?","choices":["<em>Иванушку любит Василиса</em>.","<em>Дни сменяют ночи</em>.","<em>Вытащил богатырь волшебный меч</em>.","<em>Море горы скрыло</em>.","<em>Копейка рубль бережёт</em>."],"key":"Б","review":["Кто выполняет действие?","В большинстве фраз форму или число подлежащего можно узнать: «Василиса» стоит в именительном падеже, а «скрыло» подходит к «море».","«Дни» и «ночи» могут быть и подлежащим, и дополнением. «Дни сменяют ночи» допускает два смысла: дни приходят на смену ночам или ночи — на смену дням."]},{"author":"Л. Фёдорова","question":"В сказке «Конёк-Горбунок» Иванушка просит у царя в обмен на коней «<em>два-пять</em> <em>шапок серебра</em>». Сколько это?","choices":["от двух до пяти, сколько дадут","двадцать пять","семь","две с половиной","десять."],"key":"Д","review":["Шапки серебра","В сказках встречается счёт вроде «тридевять»: три раза по девять. Попробуй так же прочитать «два-пять».","Два раза по пять — десять. Иванушка просит десять шапок серебра."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
